// Firmar y verificar un webhook con HMAC-SHA256 (WebCrypto, corre acá mismo). Secreto falso, datos inventados.
const enc = new TextEncoder();
const SECRETO = 'whsec_FALSO_solo_para_practicar';

async function firmar(id, ts, cuerpo) {
  const llave = await crypto.subtle.importKey('raw', enc.encode(SECRETO), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const mac = new Uint8Array(await crypto.subtle.sign('HMAC', llave, enc.encode(`${id}.${ts}.${cuerpo}`)));
  return [...mac].map((b) => b.toString(16).padStart(2, '0')).join('');
}
function iguales(a, b) {                    // compara siempre todo el largo, sin cortar en la primera diferencia
  let d = a.length ^ b.length;
  for (let i = 0; i < Math.max(a.length, b.length); i++) d |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return d === 0;
}
const vistos = new Set();                   // en serio: una tabla con el id como clave primaria
async function recibir(m, ahora) {
  if (!iguales(m.firma, await firmar(m.id, m.ts, m.cuerpo))) return 'rechazado: firma inválida';
  if (Math.abs(ahora - m.ts) > 300) return 'rechazado: fuera de la ventana de 5 minutos';
  if (vistos.has(m.id)) return 'ya procesado: se ignora (pero se responde 200)';
  vistos.add(m.id);
  return 'aceptado: ' + JSON.parse(m.cuerpo).estado;
}

const ahora = 1_800_000_000;                // un «ahora» fijo, para que la salida sea siempre igual
const cuerpo = '{"estado":"entregado"}';
const bueno = { id: 'evt_1', ts: ahora - 3, cuerpo, firma: await firmar('evt_1', ahora - 3, cuerpo) };

console.log('1. mensaje auténtico    ->', await recibir(bueno, ahora));
console.log('2. el mismo, repetido   ->', await recibir(bueno, ahora + 1));
console.log('3. cuerpo alterado      ->', await recibir({ ...bueno, cuerpo: '{"estado":"cancelado"}' }, ahora));
console.log('4. timestamp cambiado   ->', await recibir({ ...bueno, ts: ahora }, ahora));
const viejo = { id: 'evt_0', ts: ahora - 900, cuerpo, firma: await firmar('evt_0', ahora - 900, cuerpo) };
console.log('5. auténtico pero viejo ->', await recibir(viejo, ahora));
console.log('firma de ejemplo        :', bueno.firma.slice(0, 16) + '…');

